import React from 'react';
import { Platform, StatusBar as RNStatusBar, StyleSheet, View } from 'react-native';
import { StatusBar } from 'expo-status-bar';
import { WebView } from 'react-native-webview';
import { HTML_CONTENT } from './src/htmlContent';

// The flow map is a fully self-contained HTML page (data snapshot embedded).
// It is bundled as a string module (src/htmlContent.ts, generated by
// scripts/sync-html.mjs from ../42-flowmap/index.html) and rendered
// full-screen in a WebView. No network access is needed or allowed.
//
// Safe areas: the WebView sits inside a container padded by the Android
// status-bar height (top) and a fixed nav-bar allowance (bottom), on the
// page's own background colour — in v1 the page ran edge-to-edge, so the
// title collided with the status bar and the legend was cut by the nav bar.
// (react-native-safe-area-context is not a dependency of this project, so
// StatusBar.currentHeight + a fixed bottom padding is used instead.)
const TOP_INSET = Platform.OS === 'android' ? RNStatusBar.currentHeight ?? 24 : 0;
const BOTTOM_INSET = 36;

export default function App() {
  return (
    <View style={[styles.root, { paddingTop: TOP_INSET, paddingBottom: BOTTOM_INSET }]}>
      <StatusBar style="light" />
      <WebView
        source={{ html: HTML_CONTENT, baseUrl: 'https://localhost/' }}
        originWhitelist={['*']}
        javaScriptEnabled
        domStorageEnabled={false}
        style={styles.webview}
        containerStyle={styles.webview}
        onShouldStartLoadWithRequest={(req) =>
          req.url === 'https://localhost/' ||
          req.url.startsWith('about:') ||
          req.url.startsWith('data:')
        }
        setSupportMultipleWindows={false}
        overScrollMode="never"
        textZoom={100}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  root: { flex: 1, backgroundColor: '#050914' },
  webview: { flex: 1, backgroundColor: '#050914' },
});
